import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { pathToFileURL } from "node:url";

const GENERATED_MARKER =
  "# @generated by nuthouse/scripts/sync-codex-agents.mjs; edit the Claude agent source instead.";
const LEGACY_GENERATED_MARKER =
  "# Generated by scripts/sync-codex-agents.mjs; edit the Claude agent source instead.";
const RUNTIME_MAP_MARKER =
  "<!-- @generated by nuthouse/scripts/sync-codex-agents.mjs; edit canonical agents and skills instead. -->";
const RUNTIME_MAP_FILENAME = "agent-runtime-map.md";
const SOURCE_NAME_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

const MODEL_MAP = new Map([
  ["haiku", "gpt-5.6-luna"],
  ["sonnet", "gpt-5.6-terra"],
  ["opus", "gpt-5.6-sol"],
]);

const SANDBOX_POLICIES = new Map([
  ["git-gremlin:commit-drafter", { mode: "workspace-write" }],
  ["git-gremlin:pr-drafter", { mode: "workspace-write", networkAccess: true }],
  ["moon-moth:verify-runner", { mode: "workspace-write" }],
  ["stack-golem:platform-scout", { mode: "workspace-write", networkAccess: true }],
]);

function parseScalar(frontmatter, key) {
  const match = frontmatter.match(new RegExp(`^${key}:[ \\t]*([^\\n]*)$`, "m"));
  if (!match) return undefined;
  const value = match[1].trim();
  return value || undefined;
}

function parseInlineList(frontmatter, key) {
  const value = parseScalar(frontmatter, key);
  if (!value?.startsWith("[") || !value.endsWith("]")) return [];
  return value
    .slice(1, -1)
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
}

function parseBlockList(frontmatter, key) {
  const lines = frontmatter.split("\n");
  const start = lines.findIndex((line) => line === `${key}:`);
  if (start === -1) return [];

  const values = [];
  for (const line of lines.slice(start + 1)) {
    const match = line.match(/^  - (.+)$/);
    if (!match) break;
    values.push(match[1].trim());
  }
  return values;
}

function parseClaudeAgent(source, sourcePath, plugin) {
  const match = source.match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
  if (!match) throw new Error(`${sourcePath}: missing YAML frontmatter`);

  const [, frontmatter, rawBody] = match;
  const name = parseScalar(frontmatter, "name");
  const description = parseScalar(frontmatter, "description");
  if (!name || !description) throw new Error(`${sourcePath}: missing name or description`);

  return {
    body: rawBody.trim(),
    description,
    effort: parseScalar(frontmatter, "effort"),
    maxTurns: parseScalar(frontmatter, "maxTurns"),
    model: parseScalar(frontmatter, "model"),
    name,
    plugin,
    skills: parseInlineList(frontmatter, "skills"),
    sourcePath,
    tools: parseBlockList(frontmatter, "tools"),
  };
}

function codexNameComponent(value, label) {
  if (!SOURCE_NAME_PATTERN.test(value)) {
    throw new Error(
      `${label} ${JSON.stringify(value)} must use lowercase letters, digits, and single hyphens`,
    );
  }
  return value.replaceAll("-", "_");
}

export function codexAgentName(plugin, name) {
  return `${codexNameComponent(plugin, "plugin")}` + `__${codexNameComponent(name, "agent name")}`;
}

function legacyCodexAgentName(plugin, name) {
  return `${plugin}_${name}`.replaceAll("-", "_").replace(/[^a-z0-9_]/g, "_");
}

function tomlString(value) {
  return JSON.stringify(value);
}

function renderAgent(agent, { marker, name, description }) {
  const qualifiedName = `${agent.plugin}:${agent.name}`;
  const sandboxPolicy = SANDBOX_POLICIES.get(qualifiedName) ?? { mode: "read-only" };
  const model = agent.model === "inherit" ? undefined : MODEL_MAP.get(agent.model);
  if (agent.model && agent.model !== "inherit" && !model) {
    throw new Error(`${agent.sourcePath}: unsupported Claude model ${agent.model}`);
  }

  const metadata = [
    `This is the Codex port of logical agent \`${qualifiedName}\`.`,
    `Select this custom agent whenever a skill delegates to \`${qualifiedName}\`.`,
    `Canonical source: \`${agent.sourcePath}\`.`,
    agent.maxTurns
      ? `Stop after at most ${agent.maxTurns} agentic turns and return the best evidence available.`
      : null,
    agent.skills.length > 0
      ? `Load and follow these available skills before acting: ${agent.skills.map((skill) => `\`${skill}\``).join(", ")}.`
      : null,
    agent.tools.length > 0
      ? `Use only the closest available Codex equivalents of these Claude capabilities: ${agent.tools.join(", ")}.`
      : null,
    "Translate Claude-specific tool names to the equivalent Codex tool or connector; preserve every approval and mutation gate.",
  ].filter(Boolean);
  const instructions = [...metadata, "", agent.body].join("\n");
  if (instructions.includes("'''")) {
    throw new Error(`${agent.sourcePath}: generated instructions contain a TOML literal delimiter`);
  }

  const lines = [marker, `name = ${tomlString(name)}`, `description = ${tomlString(description)}`];

  if (model) lines.push(`model = ${tomlString(model)}`);
  if (agent.effort) lines.push(`model_reasoning_effort = ${tomlString(agent.effort)}`);
  lines.push(`sandbox_mode = ${tomlString(sandboxPolicy.mode)}`);
  if (sandboxPolicy.networkAccess) {
    lines.push("sandbox_workspace_write.network_access = true");
  }
  lines.push("", "developer_instructions = '''", instructions, "'''", "");
  return lines.join("\n");
}

export function renderCodexAgent(agent) {
  const qualifiedName = `${agent.plugin}:${agent.name}`;
  return renderAgent(agent, {
    marker: GENERATED_MARKER,
    name: codexAgentName(agent.plugin, agent.name),
    description:
      `${agent.description} Logical agent ID: ${qualifiedName}. ` +
      "Spawn with isolated task-local context, never a full-history fork.",
  });
}

function renderLegacyCodexAgent(agent) {
  const qualifiedName = `${agent.plugin}:${agent.name}`;
  const content = renderAgent(agent, {
    marker: LEGACY_GENERATED_MARKER,
    name: legacyCodexAgentName(agent.plugin, agent.name),
    description: `${agent.description} Claude alias: ${qualifiedName}.`,
  });
  return content.replace(
    `This is the Codex port of logical agent \`${qualifiedName}\`.\nSelect this custom agent whenever a skill delegates to \`${qualifiedName}\`.`,
    `This is the Codex port of Claude Code subagent \`${qualifiedName}\`.`,
  );
}

export function listAgentSources(repoRoot) {
  const agents = [];
  for (const entry of fs.readdirSync(repoRoot, { withFileTypes: true })) {
    if (!entry.isDirectory() || entry.name.startsWith(".") || entry.name.startsWith("_")) continue;
    const agentsDir = path.join(repoRoot, entry.name, "agents");
    if (!fs.existsSync(agentsDir)) continue;

    for (const filename of fs.readdirSync(agentsDir).sort()) {
      if (!filename.endsWith(".md")) continue;
      const sourcePath = path.posix.join(entry.name, "agents", filename);
      const source = fs.readFileSync(path.join(repoRoot, sourcePath), "utf8");
      agents.push(parseClaudeAgent(source, sourcePath, entry.name));
    }
  }
  return agents;
}

function markdownFiles(directory) {
  if (!fs.existsSync(directory)) return [];
  return fs.readdirSync(directory, { withFileTypes: true }).flatMap((entry) => {
    const target = path.join(directory, entry.name);
    if (entry.isDirectory()) return markdownFiles(target);
    return entry.isFile() && entry.name.endsWith(".md") ? [target] : [];
  });
}

function buildAgentFiles(agents, nameForAgent, renderAgentFile) {
  const files = new Map();
  const sourcesByFilename = new Map();

  for (const agent of agents) {
    const filename = `${nameForAgent(agent)}.toml`;
    const previousSource = sourcesByFilename.get(filename);
    if (previousSource) {
      throw new Error(
        `Codex agent name collision: ${previousSource} and ${agent.sourcePath} both map to ${filename}`,
      );
    }
    sourcesByFilename.set(filename, agent.sourcePath);
    files.set(filename, renderAgentFile(agent));
  }

  return files;
}

export function expectedAgentFiles(repoRoot) {
  return buildAgentFiles(
    listAgentSources(repoRoot),
    (agent) => codexAgentName(agent.plugin, agent.name),
    renderCodexAgent,
  );
}

export function legacyExpectedAgentFiles(repoRoot) {
  return buildAgentFiles(
    listAgentSources(repoRoot),
    (agent) => legacyCodexAgentName(agent.plugin, agent.name),
    renderLegacyCodexAgent,
  );
}

function renderRuntimeMap(agents) {
  const headers = ["Logical id", "Claude Code", "Codex"];
  const rows = agents.map((agent) => {
    const logicalName = `${agent.plugin}:${agent.name}`;
    return [
      `\`${logicalName}\``,
      `\`${logicalName}\``,
      `\`${codexAgentName(agent.plugin, agent.name)}\``,
    ];
  });
  const widths = headers.map((header, index) =>
    Math.max(header.length, ...rows.map((row) => row[index].length)),
  );
  const renderRow = (row) =>
    `| ${row.map((cell, index) => cell.padEnd(widths[index])).join(" | ")} |`;
  const table = [
    renderRow(headers),
    renderRow(widths.map((width) => "-".repeat(width))),
    ...rows.map(renderRow),
  ].join("\n");

  return `${RUNTIME_MAP_MARKER}

# Agent runtime map

Resolve every logical agent id through this table before delegation. Select the exact name
for the active runtime.

${table}

On Codex, spawn a typed custom agent with isolated task-local context. Never use a
full-history fork. Pass only the input contract required by the delegated task.
`;
}

export function expectedRuntimeMapFiles(repoRoot) {
  const agents = listAgentSources(repoRoot);
  const files = new Map();

  for (const entry of fs.readdirSync(repoRoot, { withFileTypes: true })) {
    if (!entry.isDirectory() || entry.name.startsWith(".") || entry.name.startsWith("_")) continue;
    const skillsDirectory = path.join(repoRoot, entry.name, "skills");
    const skillBody = markdownFiles(skillsDirectory)
      .map((filename) => fs.readFileSync(filename, "utf8"))
      .join("\n");
    const referencedAgents = agents
      .filter((agent) => skillBody.includes(`${agent.plugin}:${agent.name}`))
      .sort((left, right) =>
        `${left.plugin}:${left.name}`.localeCompare(`${right.plugin}:${right.name}`),
      );
    if (referencedAgents.length === 0) continue;

    files.set(
      path.join(repoRoot, entry.name, "shared", RUNTIME_MAP_FILENAME),
      renderRuntimeMap(referencedAgents),
    );
  }

  return files;
}

function tomlFiles(destination) {
  if (!fs.existsSync(destination)) return [];
  return fs.readdirSync(destination).filter((filename) => filename.endsWith(".toml"));
}

export function planAgentSync(repoRoot, destination) {
  const expected = expectedAgentFiles(repoRoot);
  const legacyExpected = legacyExpectedAgentFiles(repoRoot);
  const writes = [];
  const deletes = [];
  const conflicts = [];

  for (const [filename, content] of expected) {
    const target = path.join(destination, filename);
    if (!fs.existsSync(target)) {
      writes.push({ content, existing: undefined, filename, reason: "missing", target });
      continue;
    }

    const existing = fs.readFileSync(target, "utf8");
    if (existing === content) continue;
    if (existing.startsWith(GENERATED_MARKER)) {
      writes.push({ content, existing, filename, reason: "stale", target });
      continue;
    }
    conflicts.push(`${target}: refusing to overwrite an unmanaged file`);
  }

  for (const filename of tomlFiles(destination)) {
    if (expected.has(filename)) continue;
    const target = path.join(destination, filename);
    const existing = fs.readFileSync(target, "utf8");

    if (existing.startsWith(GENERATED_MARKER)) {
      deletes.push({ existing, filename, reason: "orphaned", target });
      continue;
    }

    if (!legacyExpected.has(filename)) continue;
    if (existing === legacyExpected.get(filename)) {
      deletes.push({ existing, filename, reason: "legacy migration", target });
      continue;
    }
    if (existing.startsWith(LEGACY_GENERATED_MARKER)) {
      conflicts.push(`${target}: legacy generated file was modified; refusing to remove it`);
    }
  }

  return {
    conflicts,
    deletes,
    destination,
    expectedCount: expected.size,
    label: "Codex agents",
    writes,
  };
}

export function planRuntimeMapSync(repoRoot) {
  const expected = expectedRuntimeMapFiles(repoRoot);
  const writes = [];
  const deletes = [];
  const conflicts = [];

  for (const [target, content] of expected) {
    const filename = path.relative(repoRoot, target);
    if (!fs.existsSync(target)) {
      writes.push({ content, existing: undefined, filename, reason: "missing", target });
      continue;
    }

    const existing = fs.readFileSync(target, "utf8");
    if (existing === content) continue;
    if (existing.startsWith(RUNTIME_MAP_MARKER)) {
      writes.push({ content, existing, filename, reason: "stale", target });
      continue;
    }
    conflicts.push(`${target}: refusing to overwrite an unmanaged runtime map`);
  }

  for (const entry of fs.readdirSync(repoRoot, { withFileTypes: true })) {
    if (!entry.isDirectory() || entry.name.startsWith(".") || entry.name.startsWith("_")) continue;
    const target = path.join(repoRoot, entry.name, "shared", RUNTIME_MAP_FILENAME);
    if (!fs.existsSync(target) || expected.has(target)) continue;
    const existing = fs.readFileSync(target, "utf8");
    if (existing.startsWith(RUNTIME_MAP_MARKER)) {
      deletes.push({
        existing,
        filename: path.relative(repoRoot, target),
        reason: "orphaned",
        target,
      });
    }
  }

  return {
    conflicts,
    deletes,
    destination: repoRoot,
    expectedCount: expected.size,
    label: "agent runtime maps",
    writes,
  };
}

export function checkAgents(repoRoot, destination) {
  const plan = planAgentSync(repoRoot, destination);
  return [
    ...plan.conflicts.map((problem) => `conflict ${problem}`),
    ...plan.writes.map(({ filename, reason }) => `${reason} ${filename}`),
    ...plan.deletes.map(({ filename, reason }) => `${reason} ${filename}`),
  ];
}

export function checkRuntimeMaps(repoRoot) {
  const plan = planRuntimeMapSync(repoRoot);
  return [
    ...plan.conflicts.map((problem) => `conflict ${problem}`),
    ...plan.writes.map(({ filename, reason }) => `${reason} ${filename}`),
    ...plan.deletes.map(({ filename, reason }) => `${reason} ${filename}`),
  ];
}

function assertConflictFree(plans) {
  const conflicts = plans.flatMap((plan) => plan.conflicts);
  if (conflicts.length === 0) return;
  throw new Error(`Codex agent sync refused:\n- ${conflicts.join("\n- ")}`);
}

let temporaryFileCounter = 0;

function atomicWriteFile(target, content, refuseExisting) {
  const temporary = path.join(
    path.dirname(target),
    `.${path.basename(target)}.tmp-${process.pid}-${temporaryFileCounter++}`,
  );
  try {
    fs.writeFileSync(temporary, content, { flag: "wx" });
    if (refuseExisting) {
      fs.linkSync(temporary, target);
      fs.rmSync(temporary);
    } else {
      fs.renameSync(temporary, target);
    }
  } finally {
    if (fs.existsSync(temporary)) fs.rmSync(temporary);
  }
}

function assertPlanStillCurrent(plan) {
  const changes = [];

  for (const { existing, reason, target } of plan.writes) {
    if (reason === "missing" && fs.existsSync(target)) {
      changes.push(`${target}: appeared after planning`);
      continue;
    }
    if (
      reason === "stale" &&
      (!fs.existsSync(target) || fs.readFileSync(target, "utf8") !== existing)
    ) {
      changes.push(`${target}: changed after planning`);
    }
  }

  for (const { existing, target } of plan.deletes) {
    if (fs.existsSync(target) && fs.readFileSync(target, "utf8") !== existing) {
      changes.push(`${target}: changed after planning`);
    }
  }

  if (changes.length > 0) {
    throw new Error(`Codex agent sync plan is stale:\n- ${changes.join("\n- ")}`);
  }
}

export function applyAgentPlan(plan) {
  assertConflictFree([plan]);
  assertPlanStillCurrent(plan);
  for (const { target } of plan.writes) {
    fs.mkdirSync(path.dirname(target), { recursive: true });
  }

  for (const { content, reason, target } of plan.writes) {
    atomicWriteFile(target, content, reason === "missing");
  }
  for (const { target } of plan.deletes) {
    if (fs.existsSync(target)) fs.rmSync(target);
  }
  return plan.expectedCount;
}

export function syncAgents(repoRoot, destination) {
  const plan = planAgentSync(repoRoot, destination);
  applyAgentPlan(plan);
  return plan.expectedCount;
}

function parseArguments(args) {
  return {
    check: args.includes("--check"),
    dryRun: args.includes("--dry-run"),
    install: args.includes("--install"),
  };
}

function printPlan(plan, futureTense) {
  const verb = futureTense ? "Would synchronize" : "Synchronized";
  console.log(
    `${verb} ${plan.expectedCount} ${plan.label} in ${plan.destination} ` +
      `(${plan.writes.length} writes, ${plan.deletes.length} removals).`,
  );
}

function main() {
  const repoRoot = path.resolve(import.meta.dirname, "..");
  const projectDestination = path.join(repoRoot, ".codex", "agents");
  const { check, dryRun, install } = parseArguments(process.argv.slice(2));
  const destinations = [projectDestination];
  if (install) destinations.push(path.join(os.homedir(), ".codex", "agents"));

  const runtimeMapPlan = planRuntimeMapSync(repoRoot);
  const agentPlans = destinations.map((destination) => planAgentSync(repoRoot, destination));
  const plans = [runtimeMapPlan, ...agentPlans];
  if (check) {
    const problems = [
      ...checkRuntimeMaps(repoRoot).map((problem) => `${repoRoot}: ${problem}`),
      ...agentPlans.flatMap((plan) =>
        checkAgents(repoRoot, plan.destination).map((problem) => `${plan.destination}: ${problem}`),
      ),
    ];
    if (problems.length > 0) {
      console.error(`Codex agents are out of sync:\n- ${problems.join("\n- ")}`);
      process.exitCode = 1;
      return;
    }
    console.log(
      `Codex agents and runtime maps are in sync ` +
        `(${agentPlans[0].expectedCount} agents, ${runtimeMapPlan.expectedCount} maps).`,
    );
    return;
  }

  try {
    assertConflictFree(plans);
    if (!dryRun) plans.forEach(applyAgentPlan);
    plans.forEach((plan) => printPlan(plan, dryRun));
  } catch (error) {
    console.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main();
